start_secure_session();require_once '../config/database.php';if(($_SESSION['role']??'')!=='dentist'){header('Location: ../auth/login.php');exit;}$uid=(int)$_SESSION['user_id'];$id=(int)($_GET['id']??0);$st=$conn->prepare("SELECT ro.*,CONCAT(p.first_name,' ',p.last_name) patient_name,CONCAT(d.first_name,' ',d.last_name) dentist_name FROM restoration_orders ro JOIN users p ON p.id=ro.patient_id JOIN users d ON d.id=ro.dentist_id WHERE ro.id=? AND ro.dentist_id=? LIMIT 1");$st->bind_param('ii',$id,$uid);$st->execute();$o=$st->get_result()->fetch_assoc();$st->close();if(!$o){header('Location: treatment_plans.php');exit;}$teeth=json_decode($o['selected_teeth']?:'[]',true)?:[];$work=json_decode($o['work_options']?:'[]',true)?:[];$mat=json_decode($o['teeth_material_options']?:'[]',true)?:[];$stain=json_decode($o['staining_options']?:'[]',true)?:[];require '../includes/ui.php';ui_header('Restoration Plan','dentist');ui_sidebar('dentist','treatment_plans.php');?>
<div class="page-head"><div><div class="eyebrow"><?=e(strtoupper($o['restoration_type']))?> RESTORATION</div><h1><?=e(ucfirst($o['restoration_type']))?> Restoration Plan</h1><div class="muted"><?=e($o['patient_name'])?> · <?=e($o['order_no']?:'No order number')?></div></div><div class="actions"><a class="btn btn-secondary" href="restoration_form.php?id=<?=$o['id']?>">Edit</a><button class="btn btn-secondary" onclick="window.print()">Print</button></div></div><?php if(isset($_GET['saved']))flash('success','Treatment plan saved.');?><section class="card"><div class="restoration-summary"><div><b>Patient</b><span><?=e($o['patient_name'])?></span></div><div><b>Dentist</b><span><?=e($o['dentist_name'])?></span></div><div><b>Date Sent / Due</b><span><?=e($o['date_sent']?:'—')?> / <?=e($o['date_due']?:'—')?></span></div><div><b>Status</b><span><?=e($o['status'])?></span></div></div><div class="form-section-title">Selected Teeth</div><p><?=e($teeth?implode(', ',$teeth):'None')?><?php if($teeth&&$o['restoration_type']==='fixed'):?> <span class="muted">(<?=e(implode(', ',array_map(static fn($t)=>(['1'=>'UR','2'=>'UL','3'=>'LL','4'=>'LR'][$t[0]]??'').$t[1],$teeth)))?>)</span><?php endif;?></p><div class="form-section-title">Type of Work</div><p><?=e($work?implode(', ',$work):'None')?></p><div class="form-section-title"><?=$o['restoration_type']==='fixed'?'Alloy / Margin / Materials':'Type of Teeth'?></div><p><?=e($mat?implode(', ',$mat):'None')?></p><?php if($o['restoration_type']==='fixed'):?><div class="form-section-title">Staining / Design</div><p><?=e(($stain?implode(', ',$stain).' · ':'').($o['metal_design']?:'No metal design').' · '.($o['pontic_design']?:'No pontic design'))?></p><?php endif;?><div class="form-section-title">Shade / Mould</div><p><?=e(($o['shade']?:'—').' / '.($o['mould']?:'—'))?></p><div class="form-section-title">Instructions</div><div class="message-body"><?=e($o['instructions']?:'No additional instructions.')?></div></section><?php ui_footer();?>
